  Lemma x_ctor : forall (Q : machine_state -> Prop) R F fc m XSc sk LBk RT SF FT HT,
    rfull R -> rtbl Wx R RT -> ftbl Wx (xS1 e) m SF -> ftbl Wx ff m FT -> ftbl Wx (ff / 8) m HT -> Px XSc sk LBk m -> mem_inv asegs m ->
    PropExec.getr R 10 = Z_to_bv 64 ds -> PropExec.getr R 11 = Z_to_bv 64 (ff + 32) -> PropExec.getr R 12 = Z_to_bv 64 pcons ->
    PropExec.getr R 13 = Z_to_bv 64 (ff + 96) -> PropExec.getr R 14 = Z_to_bv 64 ((-4) mod 2 ^ 64) ->
    PropExec.getr R 15 = Z_to_bv 64 (ff + 160) -> PropExec.getr R 2 = Z_to_bv 64 (xS1 e) ->
    forallb (fun j => fent_in (SHBASE + 224 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (392 / 8))) = true ->
    forallb (fun j => fent_in (SHBASE + 32 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
    forallb (fun j => fent_in (SHBASE + 96 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
    forallb (fun j => fent_in (SHBASE + 160 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
    fent_in (32, 8%nat, ELit 0) FT = true -> fent_in (32 + 8, 8%nat, ELit 0) FT = true -> fent_in (32 + 16, 8%nat, EVar 55) FT = true ->
    fent_in (96, 2%nat, ELit 0) FT = true -> fent_in (160, 2%nat, ELit 0) FT = true ->
    fin 0 56 (fkeys SF) = true -> fin 0 224 (fkeys FT) = true -> fin SHBASE (SHBASE + 128) (fkeys HT) = true ->
    (forall R2 m2, rfull R2 -> (forall r, In r KEPT -> PropExec.getr R2 r = PropExec.getr R r) ->
       ftbl Wx (xS1 e) m2 SF -> ftbl Wx ff m2 FT -> ftbl Wx (ff / 8) m2 HT -> Px XSc sk LBk m2 -> mem_inv asegs m2 ->
       (forall LB, ds_repA0 LB m2 ds (-4) 0 []) ->
       evt asegs Q (MS R2 F (ret_pc (PropExec.getr R 1)) fc None m2 (seg_rom asegs))) ->
    evt asegs Q (MS R F (Z_to_bv 64 ADS_CTOR) fc None m (seg_rom asegs)).
